using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Weil.ZetaBridge;

internal sealed class ActualThreeNodeFiniteEnergyDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Actual three-node FiniteEnergy", H("Actual three-node FiniteEnergy"),
        Blocks(
            Paragraph(Text("The signed integer nodes are the sealed owner's literal set {-n,0,n}; n is any nonzero integer. The same owner supplies the normalized source heads and sourceHead. No new Hilbert-space bridge, summability theorem or positivity definition is introduced here.")),
            Paragraph(Text("Nodal expansion derives D=X(X^2-n^2), Q=(v(-n)+v(0)+v(n))X^2+n(v(n)-v(-n))X-n^2 v(0), and P=a(v(n)-v(-n))X^2+an(v(n)+v(-n))X from the actual arithmetic symbol and its oddness.")),
            Paragraph(Text("For raw coordinates v=p(1,1,1)+q(-1,0,1)+s(1,-2,1), reciprocal evaluation gives A(t)=2aq+2ar(p+s)t and B(t)=3p+2rq t+r^2(-p+2s)t^2. Both exterior signs are kept before integration. All p,q,s are complex and may vanish or cancel.")),
            Paragraph(Text("The paired energy integral is U|p|^2+2O|q|^2+C|s|^2+2T Re(conj(p)s). Substituting p=x(0)/sqrt(3), q=x(1)/sqrt(2), s=x(2)/sqrt(6) gives the Hermitian matrix [[U/3,0,T/sqrt(18)],[0,O,0],[T/sqrt(18),0,C/6]].")),
            Paragraph(Text("The sealed sourceHead_original_norm theorem identifies the original retained coefficient mass with the Euclidean mass of x. The realized matrix therefore uses that original metric; it is derived from actual P,Q and pairedEnergy, rather than selected as an unrelated Hermitian matrix.")),
            Describe.Lean(DescribeId.Create("nodes-distinct"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.nodes_distinct"),
                H("nodes distinct"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma nodes_distinct {n : ℤ} (hn : n ≠ 0) :\n    -n ≠ 0 ∧ -n ≠ n ∧ (0 : ℤ) ≠ n"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("three-nodes-card"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.threeNodes_card"),
                H("threeNodes card"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma threeNodes_card {n : ℤ} (hn : n ≠ 0) : (threeNodes n).card = 3"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("actual-symbol-zero"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.actual_symbol_zero"),
                H("actual symbol zero"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma actual_symbol_zero (c : ℕ) : arithmeticBoundarySymbol c 0 = 0"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("actual-three-nodal"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.actual_three_nodal"),
                H("actual three nodal"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma actual_three_nodal {n : ℤ} (hn : n ≠ 0) (c : ℕ) (v : ℤ → ℂ) :\n    D (threeNodes n) = X * (X ^ 2 - C ((n : ℂ) ^ 2)) ∧\n    Q (threeNodes n) v =\n      C (v (-n) + v 0 + v n) * X ^ 2 +\n        C ((n : ℂ) * (v n - v (-n))) * X - C ((n : ℂ) ^ 2 * v 0) ∧\n    P c (threeNodes n) v =\n      C ((arithmeticBoundarySymbol c n : ℂ) * (v n - v (-n))) * X ^ 2 +\n        C ((arithmeticBoundarySymbol c n : ℂ) * (n : ℂ) * (v n + v (-n))) * X"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("raw-head"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.rawHead"),
                H("rawHead"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("def rawHead (n : ℤ) (p q s : ℂ) : ℤ → ℂ :=\n  p • (singletonHead (-n) + singletonHead 0 + singletonHead n) +\n  q • (-singletonHead (-n) + singletonHead n) +\n  s • (singletonHead (-n) - 2 • singletonHead 0 + singletonHead n)"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("raw-head-nodes"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.rawHead_nodes"),
                H("rawHead nodes"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma rawHead_nodes {n : ℤ} (hn : n ≠ 0) (p q s : ℂ) :\n    rawHead n p q s (-n) = p - q + s ∧\n    rawHead n p q s 0 = p - 2 * s ∧\n    rawHead n p q s n = p + q + s"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("source-head-eq-raw-head"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.sourceHead_eq_rawHead"),
                H("sourceHead eq rawHead"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma sourceHead_eq_rawHead (n : ℤ) (x : Fin 3 → ℂ) :\n    sourceHead n x = rawHead n (x 0 / (Real.sqrt 3 : ℂ))\n      (x 1 / (Real.sqrt 2 : ℂ)) (x 2 / (Real.sqrt 6 : ℂ))"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("raw-a"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.rawA"),
                H("rawA"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("def rawA (a r : ℝ) (p q s : ℂ) : ℂ[X] :=\n  C (2 * (a : ℂ) * q) + C (2 * (a : ℂ) * (r : ℂ) * (p + s)) * X"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("raw-b"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.rawB"),
                H("rawB"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("def rawB (r : ℝ) (p q s : ℂ) : ℂ[X] :=\n  C (3 * p) + C (2 * (r : ℂ) * q) * X +\n    C ((r : ℂ) ^ 2 * (-p + 2 * s)) * X ^ 2"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("reciprocal-three"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.reciprocal_three"),
                H("reciprocal three"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma reciprocal_three (N : ℕ) (b0 b1 b2 : ℂ) :\n    reciprocalPolynomial 3 N (C b0 + C b1 * X + C b2 * X ^ 2) =\n      C b2 + C (b1 / (N : ℂ)) * X + C (b0 / (N : ℂ) ^ 2) * X ^ 2"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("actual-raw-reciprocals"),
