                Blocks(Paragraph(Text("def mixed (p s : ℂ) : ℝ := (conj p * s).re"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("raw-integrand"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.rawIntegrand"),
                H("rawIntegrand"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("def rawIntegrand (g mu a r : ℝ) (p q s : ℂ) (t : ℝ) : ℝ :=\n  ‖value (rawA a r p q s) t + (g : ℂ) * value (rawB r p q s) t‖ ^ 2 +\n  ‖value (rawA a r p q s) (-t) - (g : ℂ) * value (rawB r p q s) (-t)‖ ^ 2 +\n  mu * (‖value (rawB r p q s) t‖ ^ 2 + ‖value (rawB r p q s) (-t)‖ ^ 2)"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("quartic-coeffs"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.quarticCoeffs"),
                H("quarticCoeffs"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("def quarticCoeffs (g mu a r : ℝ) (p q s : ℂ) : Fin 5 → ℝ :=\n  ![18 * (g ^ 2 + mu) * ‖p‖ ^ 2 + 8 * a ^ 2 * ‖q‖ ^ 2,\n    24 * g * a * r * (‖p‖ ^ 2 + mixed p s) + 16 * a * g * r * ‖q‖ ^ 2,\n    (8 * a ^ 2 - 12 * (g ^ 2 + mu)) * r ^ 2 * ‖p‖ ^ 2 +\n      8 * (g ^ 2 + mu) * r ^ 2 * ‖q‖ ^ 2 + 8 * a ^ 2 * r ^ 2 * ‖s‖ ^ 2 +\n      (16 * a ^ 2 + 24 * (g ^ 2 + mu)) * r ^ 2 * mixed p s,\n    8 * a * g * r ^ 3 * (-‖p‖ ^ 2 + 2 * ‖s‖ ^ 2 + mixed p s),\n    2 * (g ^ 2 + mu) * r ^ 4 * (‖p‖ ^ 2 + 4 * ‖s‖ ^ 2 - 4 * mixed p s)]"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("raw-integrand-parity-pair"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.rawIntegrand_parity_pair"),
