                Blocks(Paragraph(Text("lemma rawIntegrand_parity_pair (g mu a r : ℝ) (p q s : ℂ) (t : ℝ) :\n    rawIntegrand g mu a r p q s t =\n      2 * ‖value (rawA a r p 0 s) t + (g : ℂ) * value (rawB r p 0 s) t‖ ^ 2 +\n      2 * ‖value (rawA a r 0 q 0) t + (g : ℂ) * value (rawB r 0 q 0) t‖ ^ 2 +\n      2 * mu * (‖value (rawB r p 0 s) t‖ ^ 2 + ‖value (rawB r 0 q 0) t‖ ^ 2)"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("raw-integrand-quartic"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.rawIntegrand_quartic"),
                H("rawIntegrand quartic"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma rawIntegrand_quartic (g mu a r : ℝ) (p q s : ℂ) (t : ℝ) :\n    rawIntegrand g mu a r p q s t =\n      ∑ i : Fin 5, quarticCoeffs g mu a r p q s i * t ^ (i : ℕ)"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("integral-fin5-monomials"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.integral_fin5_monomials"),
                H("integral fin5 monomials"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma integral_fin5_monomials (b : Fin 5 → ℝ) :\n    (∫ t in (0 : ℝ)..1, ∑ i : Fin 5, b i * t ^ (i : ℕ)) =\n      ∑ i : Fin 5, b i / (((i : ℕ) : ℝ) + 1)"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("raw-paired-energy"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.raw_pairedEnergy"),
