                Blocks(Paragraph(Text("lemma raw_pairedEnergy (c : ℕ) (a r : ℝ) (p q s : ℂ) :\n    pairedEnergy c (rawA a r p q s) (rawB r p q s) =\n      U₃ (Real.pi / 4) (mean c) a r * ‖p‖ ^ 2 +\n      2 * O₃ (Real.pi / 4) (mean c) a r * ‖q‖ ^ 2 +\n      C₃ (Real.pi / 4) (mean c) a r * ‖s‖ ^ 2 +\n      2 * T₃ (Real.pi / 4) (mean c) a r * mixed p s"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("mixed-div-real"),
