                Blocks(Paragraph(Text("lemma mixed_div_real (p s : ℂ) (u v : ℝ) :\n    mixed (p / (u : ℂ)) (s / (v : ℂ)) = mixed p s / (u * v)"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("norm-div-sqrt-sq"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.norm_div_sqrt_sq"),
                H("norm div sqrt sq"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma norm_div_sqrt_sq (p : ℂ) {d : ℝ} (hd : 0 ≤ d) :\n    ‖p / (Real.sqrt d : ℂ)‖ ^ 2 = ‖p‖ ^ 2 / d"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("finite-form"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.finiteForm"),
