                Blocks(Paragraph(Text("def finiteForm (g mu a r : ℝ) (x : Fin 3 → ℂ) : ℝ :=\n  U₃ g mu a r / 3 * ‖x 0‖ ^ 2 + O₃ g mu a r * ‖x 1‖ ^ 2 +\n    C₃ g mu a r / 6 * ‖x 2‖ ^ 2 +\n    2 * (T₃ g mu a r / Real.sqrt 18) * mixed (x 0) (x 2)"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("finite-matrix"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.finiteMatrix"),
                H("finiteMatrix"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("def finiteMatrix (g mu a r : ℝ) : Matrix (Fin 3) (Fin 3) ℂ :=\n  !![((U₃ g mu a r / 3 : ℝ) : ℂ), 0, ((T₃ g mu a r / Real.sqrt 18 : ℝ) : ℂ);\n      0, (O₃ g mu a r : ℂ), 0;\n      ((T₃ g mu a r / Real.sqrt 18 : ℝ) : ℂ), 0, ((C₃ g mu a r / 6 : ℝ) : ℂ)]"))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("finite-matrix-form"),
