            Describe.Lean(DescribeId.Create("finite-matrix-is-hermitian"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.finiteMatrix_isHermitian"),
                H("finiteMatrix isHermitian"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("lemma finiteMatrix_isHermitian (g mu a r : ℝ) :\n    (finiteMatrix g mu a r).IsHermitian"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("actual-finite-energy-form"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.actual_finite_energy_form"),
                H("actual finite energy form"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("theorem actual_finite_energy_form {n : ℤ} (hn : n ≠ 0) (c N : ℕ) (hN : 0 < N)\n    (x : Fin 3 → ℂ) :\n    pairedEnergy c\n        (reciprocalPolynomial 3 N (P c (threeNodes n) (sourceHead n x)))\n        (reciprocalPolynomial 3 N (Q (threeNodes n) (sourceHead n x))) =\n      finiteForm (Real.pi / 4) (mean c) (arithmeticBoundarySymbol c n) ((n : ℝ) / N) x"))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("actual-finite-matrix-realization"),
                DeclarationHandle.Create("D5/S3/Weil/ZetaBridge/ActualThreeNodeFiniteEnergy.actual_finite_matrix_realization"),
